When validating that an object contains a complete set of required keys, explicitly verify against a list of expected keys rather than iterating only over the keys present in the object. Accompany this with regression tests that delete expected keys to ensure the validation fails closed.

```javascript
  const expectedBoundaryKeys = [
    'schema_version',
    'generated_at',
    'generated_by',
    'issue',
    'parent_issue',
    'depends_on_issues',
    'subject_code',
    'artifact_only',
    'boundary_only',
    'runtime_rebuild',
    'output_artifacts',
    'source_artifacts',
    'upstream_status',
    'required_decision',
    'controlled_vocabulary',
    'question_level_ms_source_view_schema',
    'canonical_record_examples',
    'reveal_policy',
    'display_policy',
    'separation_contract',
    'claim_policy',
    'preserved_runtime_baseline',
    'side_effect_receipt',
    'non_goals'
  ];
  if (!expectedBoundaryKeys.every((key) => Object.prototype.hasOwnProperty.call(boundary, key))) {
    return failClosedValidatorResult(['boundary_keys_incomplete']);
  }

  const errors = [];
  const vocabulary = boundary.controlled_vocabulary ?? {};
  const schema = boundary.question_level_ms_source_view_schema ?? {};
  const records = boundary.canonical_record_examples;
  const decision = boundary.required_decision ?? {};
  const reveal = boundary.reveal_policy ?? {};
  const display = boundary.display_policy ?? {};
  const separation = boundary.separation_contract ?? {};
  const claim = boundary.claim_policy ?? {};
  const baseline = boundary.preserved_runtime_baseline ?? {};
  const sideEffects = boundary.side_effect_receipt ?? {};
  const upstream = boundary.upstream_status ?? {};
```

<details>
<summary>References</summary>

1. When validating that an object contains a complete set of required keys, explicitly verify against a list of expected keys rather than iterating only over the keys present in the object. Accompany this with regression tests that delete expected keys to ensure the validation fails closed.
</details>

